async function download(url){
 const response=await fetch(url,{headers:{Accept:"*/*"}});
 if(!response.ok){let data;try{data=await response.json();}catch{data={};}throw new Error(data.error?.message||`Không tải được tệp (HTTP ${response.status}).`);}
 const blob=await response.blob();const objectUrl=URL.createObjectURL(blob);
 const disposition=response.headers.get("Content-Disposition")||"";const match=disposition.match(/filename="([^"]+)"/i);
 const a=el("a",{href:objectUrl,download:match?match[1]:"so-can-cu-export"});document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),30000);
}
async function exportProject(id,format){
 try{const current=await api(`/api/projects/${encodeURIComponent(id)}/check`);const issues=current.issues||[];
  const perform=async()=>{await download(`/api/projects/${encodeURIComponent(id)}/export?format=${encodeURIComponent(format)}`);toast("Đã tải hồ sơ. Bản xuất giữ nguyên các cảnh báo hiện có.");};
  if(issues.length)confirmAction("Xuất hồ sơ đang có cảnh báo?",`Hồ sơ có ${issues.length} vấn đề cần xem lại. Bản xuất sẽ ghi cả cảnh báo, nội dung luận điểm và căn cứ để tiếp tục kiểm tra.`,"Xuất kèm cảnh báo",perform);else await perform();
 }catch(e){toast(e.message,true);}
}

