window.addEventListener("hashchange",()=>renderView(location.hash.slice(1)));
$("#app-dialog").addEventListener("click",ev=>{if(ev.target===$("#app-dialog")){const rect=ev.target.getBoundingClientRect();if(ev.clientX<rect.left||ev.clientX>rect.right||ev.clientY<rect.top||ev.clientY>rect.bottom)closeDialog();}});
async function start(){try{await refreshBootstrap();await renderView(location.hash.slice(1)||"overview");}catch(e){$("#connection-status").textContent="Chưa kết nối";$("#main").setAttribute("aria-busy","false");$("#main").replaceChildren(heading("SỔ CĂN CỨ","Không kết nối được ứng dụng","Khởi động máy chủ cục bộ, sau đó tải lại trang."),el("div",{class:"alert error",role:"alert"},e.message),btn("Tải lại",()=>location.reload(),"primary","refresh"));}}start();
